import{_ as r,o as t,c as a,a2 as i}from"./chunks/framework.E8pQZ6KS.js";const c=JSON.parse('{"title":"Burp Suite 与 Web 调试","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/BurpSuite与Web调试.md","filePath":"必学工具/BurpSuite与Web调试.md","lastUpdated":1792430298000}'),o={name:"必学工具/BurpSuite与Web调试.md"};function l(n,e,u,s,p,b){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="burp-suite-与-web-调试" tabindex="-1">Burp Suite 与 Web 调试 <a class="header-anchor" href="#burp-suite-与-web-调试" aria-label="Permalink to &quot;Burp Suite 与 Web 调试&quot;">​</a></h1><blockquote><p>Web 安全测试的事实标准工具。抓包改包、扫描、重放，Web 攻防方向的一切实验都从 Burp Suite 开始。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>校内「Web 应用安全 / 网络攻防技术」与校外 CTF-Web 方向的核心工具；</li><li>理解 HTTP 请求/响应是 Web 安全的地基，Burp 是观察与修改它的最佳入口。</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>Proxy（代理）</strong>：浏览器流量经过 Burp，可拦截、查看、修改；</li><li><strong>Repeater</strong>：手动修改并重放请求（漏洞验证主力）；</li><li><strong>Intruder</strong>：自动化爆破 / 枚举；</li><li><strong>Decoder / Comparer</strong>：编码解码与报文比对；</li><li><strong>Scanner（专业版）</strong>：自动漏洞扫描（社区版功能受限）。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li>安装 Burp Suite Community（<a href="https://portswigger.net/burp" target="_blank" rel="noreferrer">PortSwigger 官网</a>），配置浏览器代理（或用 Burp 自带浏览器）；</li><li>学会用 Proxy 拦截并修改一个请求（改参数、改 Cookie）；</li><li>用 Repeater 重放，观察服务器响应变化；</li><li>到 <a href="https://portswigger.net/web-security" target="_blank" rel="noreferrer">PortSwigger Web Security Academy</a> 练手——免费、系统、含实验环境的官方课程。</li></ol><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>Web 安全方向的学习顺序：<strong>HTTP 基础 → Burp 熟练 → OWASP Top 10 → 漏洞靶场 → 真实目标</strong>；</li><li>靶场建议：DVWA、pikachu、<a href="https://github.com/WebGoat/WebGoat" target="_blank" rel="noreferrer">WebGoat</a>（见 <a href="./../实验与实践/安全实验平台.html">安全实验平台</a>）；</li><li>Burp 的英文界面别怕，核心菜单就几个，用两天就熟了。</li></ul><h2 id="合规提醒" tabindex="-1">合规提醒 <a class="header-anchor" href="#合规提醒" aria-label="Permalink to &quot;合规提醒&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Burp 的拦截与改包能力只可用于<strong>授权目标</strong>（课程实验、CTF 平台、自建靶场、签署了授权协议的测试）。</p></div>',12)])])}const d=r(o,[["render",l]]);export{c as __pageData,d as default};
